const root=document.getElementById('bloxplox-v2'),main=root.querySelector('.bp2-main'),header=root.querySelector('.bp2-header'),overlay=root.querySelector('.bp2-overlay'),app=root.querySelector('.bp2-app');
const scenes=['Blocks','Tracker / RealTracker','Blocks / mobile','Habit settings','Add a block','Overlap','Block settings','Backlog','Categories','History','Schedule habit'];
const today='2026-10-11';let date=today,scene=0,layout='grid',page='schedule',selected=2,pending=null,returnDialog=null,calMonth='2026-10',menu=false,noticeTimer,drag=null,suppressClick=false,autoBacklog=true;
const categories=[{name:'German',color:'purple',hex:'#b48aff'},{name:'Work',color:'blue',hex:'#70b4ff'},{name:'Personal',color:'orange',hex:'#ff9b57'},{name:'Movement',color:'lime',hex:'#c5ef51'},{name:'Reading',color:'yellow',hex:'#ffe35c'},{name:'Family',color:'pink',hex:'#ff86ac'}];
